type StreamRun200TexteventStreamResponse struct {
	Body          io.Reader
	Headers       StreamRun200ResponseHeaders
	ContentLength int64
}

func (response StreamRun200TexteventStreamResponse) VisitStreamRunResponse(w http.ResponseWriter) error {
	w.Header().Set("Content-Type", "text/event-stream")
	if response.ContentLength != 0 {
		w.Header().Set("Content-Length", fmt.Sprint(response.ContentLength))
	}
	w.Header().Set("X-Studio-Stream-Protocol", fmt.Sprint(response.Headers.XStudioStreamProtocol))
	w.WriteHeader(200)

	if closer, ok := response.Body.(io.ReadCloser); ok {
		defer closer.Close()
	}
	_, err := io.Copy(w, response.Body)
	return err
}

